const f = $input.first().json;
let domain = f['Domaine cible'].trim();
domain = domain.replace('https://', '').replace('http://', '').replace('www.', '').split('/')[0];
const competitors = f['Concurrents'].split('\n').map(c => c.trim()).filter(Boolean);
const seeds = f['Mots-clés seeds'].split('\n').map(s => s.trim()).filter(Boolean).slice(0, 5);
const whitelist = (f['Filtre thématique'] || '').split('\n').map(w => w.trim().toLowerCase()).filter(Boolean);
const brandExcl = (f['Exclusions marque'] || '').split('\n').map(b => b.trim().toLowerCase()).filter(Boolean);
const sheetUrl = f['URL Google Sheet'].trim();
const m = sheetUrl.match('/d/([a-zA-Z0-9_-]+)');
if (!m) throw new Error('URL Google Sheet invalide. Format attendu: https://docs.google.com/spreadsheets/d/...');
let apiKey;
try { apiKey = $env.HALOSCAN_API_KEY; } catch(e) { apiKey = null; }
if (!apiKey || apiKey === "REPLACE_WITH_YOUR_API_KEY") throw new Error("Clé API Haloscan manquante. Configurez la variable d'environnement HALOSCAN_API_KEY dans Settings > Environment Variables de n8n.");
const isLocal = (f['Activité locale'] || 'Non') === 'Oui';
const isEcommerce = (f['Vertical e-commerce'] || 'Non') === 'Oui';
const configWarnings = [];
const shortSeeds = seeds.filter(s => s.split(' ').length < 2);
if (shortSeeds.length > 0) {
  configWarnings.push('seeds_courtes: ' + shortSeeds.join(', ') + ' -- les seeds de 1 mot produisent des resultats trop larges. Preferer 2+ mots.');
}
return [{json: {config: {clientName: f['Nom du client'], domain, competitors, seeds, whitelist, brandExcl, spreadsheetId: m[1], sheetUrl, apiKey, isLocal, isEcommerce, configWarnings}}}];

function extractIntentFromSi(item) {
  // Haloscan: si_trans, si_comm, si_info, si_nav, si_local, si_brand (true/false/'NA')
  if (item.si_trans === true) return 'transactional';
  if (item.si_comm === true) return 'commercial';
  if (item.si_local === true) return 'local';
  if (item.si_info === true) return 'informational';
  if (item.si_nav === true) return 'navigational';
  if (item.si_brand === true) return 'navigational';
  return null;
}
const config = $('Build Config').first().json.config;
const r = $input.first().json;
const raw = r.data || r.results || r.lines || [];
const arr = Array.isArray(raw) ? raw : [];
const positions = arr.map(i => {
  const rawIntent = extractIntentFromSi(i);
  return {
    keyword: (i.keyword || '').toLowerCase().trim(),
    position: i.position || 999,
    url: i.url || i.page || '',
    volume: i.volume || 0,
    kvi: i.kvi ?? null,
    kgr: i.kgr ?? null,
    cpc: i.cpc || 0,
    traffic: i.traffic || 0,
    raw_intent: rawIntent
  };
}).filter(p => p.keyword);
return [{json: {config, positions}}];

function extractIntentFromSi(item) {
  // Haloscan: si_trans, si_comm, si_info, si_nav, si_local, si_brand (true/false/'NA')
  if (item.si_trans === true) return 'transactional';
  if (item.si_comm === true) return 'commercial';
  if (item.si_local === true) return 'local';
  if (item.si_info === true) return 'informational';
  if (item.si_nav === true) return 'navigational';
  if (item.si_brand === true) return 'navigational';
  return null;
}
const config = $('Build Config').first().json.config;
const mr = $('Get MISSING').first().json;
const br = $('Get BESTED').first().json;
const gapWarnings = [];

function extract(r, type) {
  const raw = r.data || r.results || r.lines || [];
  return (Array.isArray(raw) ? raw : []).map(i => {
    const rawIntent = extractIntentFromSi(i);
    return {
      keyword: (i.keyword || '').toLowerCase().trim(),
      gap_type: type,
      volume: i.volume || 0,
      kvi: i.kvi ?? null,
      kgr: i.kgr ?? null,
      cpc: i.cpc || 0,
      best_comp_pos: i.best_competitor_position || i.position || null,
      best_comp_url: i.best_competitor_url || i.url || '',
      client_pos: type === 'BESTED' ? (i.best_reference_position || i.reference_position || null) : null,
      raw_intent: rawIntent
    };
  }).filter(g => g.keyword);
}

const missing = extract(mr, 'MISSING');
const bested = extract(br, 'BESTED');

let earlyStop = false;
let earlyStopReason = '';
if (missing.length === 0 && bested.length === 0) {
  earlyStop = true;
  earlyStopReason = 'no_gap_data: Aucune donnee gap (MISSING et BESTED vides). Verifier les concurrents.';
}

if (!earlyStop && (missing.length === 0 || bested.length === 0)) {
  gapWarnings.push('donnees_gap_partielles: ' + (missing.length === 0 ? 'MISSING vide' : 'BESTED vide'));
}

const kwMap = new Map();
for (const item of missing) { kwMap.set(item.keyword, item); }
let bothCount = 0;
for (const item of bested) {
  if (kwMap.has(item.keyword)) {
    const existing = kwMap.get(item.keyword);
    existing.gap_type = 'MISSING+BESTED';
    existing.client_pos = item.client_pos;
    if (existing.volume < item.volume) existing.volume = item.volume;
    if (existing.kvi == null && item.kvi != null) existing.kvi = item.kvi;
    if (existing.kgr == null && item.kgr != null) existing.kgr = item.kgr;
    if (existing.cpc < item.cpc) existing.cpc = item.cpc;
    if (!existing.raw_intent && item.raw_intent) existing.raw_intent = item.raw_intent;
    bothCount++;
  } else {
    kwMap.set(item.keyword, item);
  }
}
const all = Array.from(kwMap.values());

if (!earlyStop && all.length < 30) {
  gapWarnings.push('peu_de_donnees: seulement ' + all.length + ' keywords gap (< 30). Brief peu representatif.');
}

console.log('Parse Gap Data: ' + missing.length + ' MISSING, ' + bested.length + ' BESTED, ' + bothCount + ' overlap, ' + all.length + ' unique keywords');
return [{json: {config, gapItems: all, missingCount: missing.length, bestedCount: bested.length, bothCount, gapWarnings, earlyStop, earlyStopReason}}];

const data = $input.first().json;
const config = data.config;
const seedResults = [];
for (const seed of config.seeds) {
  try {
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.haloscan.com/api/keywords/related',
      body: {keyword: seed, lineCount: 15, order_by: 'volume', order: 'desc'},
      headers: {'Content-Type': 'application/json', 'haloscan-api-key': config.apiKey},
      json: true
    });
    const items = r.data || r.results || r.lines || [];
    for (const i of (Array.isArray(items) ? items : [])) {
      const kw = (i.keyword || '').toLowerCase().trim();
      if (kw) seedResults.push({keyword: kw, source: 'seed', seed_origin: seed, volume: i.volume || 0, kvi: i.kvi ?? null, kgr: i.kgr ?? null, cpc: i.cpc || 0});
    }
    await new Promise(r => setTimeout(r, 500));
  } catch(e) {
    console.log('Enrich Seeds: erreur pour seed "' + seed + '": ' + e.message);
  }
}
const allKw = new Set();
for (const g of data.gapItems) allKw.add(g.keyword);
for (const s of seedResults) allKw.add(s.keyword);
const baseCap = 500;
const dynamicCap = data.gapItems.length > 300 ? Math.min(800, allKw.size) : baseCap;
const clusterInput = Array.from(allKw).slice(0, dynamicCap);
console.log('Enrich Seeds: ' + seedResults.length + ' seed kw, ' + allKw.size + ' total unique, cap=' + dynamicCap + ', sending ' + clusterInput.length);
return [{json: {...data, seedResults, clusterInput}}];

// === THE GRINDER v3 — 2-Level Clustering + Structured Output ===

const data = $('Enrich Seeds').first().json;
const config = data.config;
const cr = $input.first().json;
const dashboardWarnings = [];

if (config.configWarnings) dashboardWarnings.push(...config.configWarnings);
if (data.gapWarnings) dashboardWarnings.push(...data.gapWarnings);

// --- EARLY STOP ---
if (data.earlyStop) {
  const dashboard = {
    client: config.clientName, domain: config.domain, competitors: config.competitors,
    totalGap: 0, missingCount: data.missingCount || 0, bestedCount: data.bestedCount || 0, bothCount: 0,
    totalPositions: 0, avgScore: 0,
    alertTriggered: true, alertReason: data.earlyStopReason,
    warnings: dashboardWarnings,
    intent_override: config.isEcommerce ? 'e-commerce' : config.isLocal ? 'local' : 'standard',
    kgr_estimated_count: 0, intent_override_count: 0,
    totalClusters: 0, totalPages: 0, totalCannibalisations: 0,
    generatedAt: new Date().toISOString()
  };
  return [{json: {config, gapItems: [], posItems: [], pages: [], cannibalisations: [], dashboard, alertTriggered: true}}];
}

// --- INTENT ---
const INTENT_MAP = {
  'transactional': 'Transactionnel',
  'commercial':    'Commercial',
  'informational': 'Informationnel',
  'navigational':  'Informationnel',
  'local':         'Transactionnel'
};

function mapIntent(apiLabel) {
  if (!apiLabel) return 'Informationnel';
  const label = Array.isArray(apiLabel) ? (apiLabel[0] || '') : String(apiLabel);
  return INTENT_MAP[label.toLowerCase()] || 'Informationnel';
}

const GEO_SIGNALS = ['paris','lyon','marseille','toulouse','bordeaux','lille','nantes','strasbourg','montpellier','rennes','nice','grenoble','toulon','dijon','angers','nimes','reims','clermont','orleans','tours','metz','besancon','caen','rouen','nancy','avignon','perpignan','pres de moi','a proximite','proche','quartier','arrondissement','region','departement'];
const INFO_SIGNALS = ['comment','pourquoi','definition','c\'est quoi','qu\'est ce','tutoriel','tuto','guide pratique','explication','fonctionnement','difference entre','signification','histoire de'];

function applyIntentOverride(intent, keyword, cfg) {
  if (intent !== 'Informationnel') return intent;
  const lk = keyword.toLowerCase();
  if (cfg.isLocal && GEO_SIGNALS.some(g => lk.includes(g))) return 'Transactionnel';
  if (cfg.isEcommerce && !INFO_SIGNALS.some(s => lk.includes(s))) return 'Transactionnel';
  return intent;
}

// --- SCORING ---
function score(item) {
  let s = 0;
  s += item.kvi != null ? Math.min(item.kvi * 0.4, 40) : 15;
  if (item.kgr != null) {
    if (item.kgr <= 0.25) s += 25;
    else if (item.kgr <= 0.5) s += 20;
    else if (item.kgr <= 1) s += 10;
  } else { s += 10; item.kgr_estimated = true; }
  if (item.intent === 'Transactionnel') s += 20;
  else if (item.intent === 'Commercial') s += 15;
  else s += 5;
  if (item.gap_type === 'MISSING+BESTED') s += 25;
  else if (item.gap_type === 'MISSING') s += 15;
  else if (item.gap_type === 'BESTED') s += 10;
  if (item.cpc > 2) s += 10;
  else if (item.cpc > 1) s += 5;
  else if (item.cpc > 0.5) s += 3;
  if (item.gap_type === 'BESTED' && item.client_position != null) {
    if (item.client_position >= 11 && item.client_position <= 20) s += 10;
    else if (item.client_position >= 21 && item.client_position <= 50) s += 5;
  }
  if (item.volume != null && item.volume < 10) s -= 5;
  return Math.round(s * 10) / 10;
}

// --- BRAND / WHITELIST ---
const brandT = [...config.brandExcl];
const isB = kw => brandT.some(t => kw.includes(t));
const matchW = kw => config.whitelist.length === 0 || config.whitelist.some(w => kw.includes(w));

// --- PROCESS GAP ITEMS ---
const seedMap = new Map();
for (const s of data.seedResults) { if (!seedMap.has(s.keyword)) seedMap.set(s.keyword, s); }

const gapItems = [];
let intentOverrideCount = 0;
for (const g of data.gapItems) {
  if (isB(g.keyword) || !matchW(g.keyword)) continue;
  const si = seedMap.get(g.keyword);
  if (si) {
    if (g.kvi == null && si.kvi != null) g.kvi = si.kvi;
    if (g.kgr == null && si.kgr != null) g.kgr = si.kgr;
  }
  const baseIntent = mapIntent(g.raw_intent);
  const finalIntent = applyIntentOverride(baseIntent, g.keyword, config);
  if (finalIntent !== baseIntent) intentOverrideCount++;
  g.intent = finalIntent;
  g.client_position = g.client_pos;
  g.score = score(g);
  gapItems.push(g);
}
gapItems.sort((a, b) => b.score - a.score);

// --- PROCESS POSITIONS ---
const positions = $('Parse Positions').first().json.positions || [];
const posItems = [];
for (const p of positions) {
  if (isB(p.keyword) || !matchW(p.keyword)) continue;
  const baseIntent = mapIntent(p.raw_intent);
  p.intent = applyIntentOverride(baseIntent, p.keyword, config);
  posItems.push(p);
}

// --- CANNIBALISATIONS ---
const posUrlMap = new Map();
for (const p of posItems) {
  if (!posUrlMap.has(p.keyword)) posUrlMap.set(p.keyword, []);
  posUrlMap.get(p.keyword).push({url: p.url, position: p.position});
}
const cannibalisations = [];
for (const [kw, entries] of posUrlMap) {
  const uniqueUrls = [...new Set(entries.map(e => e.url))];
  if (uniqueUrls.length >= 2) {
    const sorted = entries.sort((a, b) => a.position - b.position);
    const posGap = sorted[1].position - sorted[0].position;
    if (posGap <= 30) {
      cannibalisations.push({
        keyword: kw, url1: sorted[0].url, pos1: sorted[0].position,
        url2: sorted[1].url, pos2: sorted[1].position,
        nb_urls: uniqueUrls.length,
        ecart: posGap,
        volume: posItems.find(p => p.keyword === kw)?.volume || 0
      });
    }
  }
}
cannibalisations.sort((a, b) => (b.volume || 0) - (a.volume || 0));

// --- CROSS-REFERENCE GAP vs POSITIONS ---
const bestPosUrl = new Map();
for (const p of posItems) {
  if (!bestPosUrl.has(p.keyword) || p.position < bestPosUrl.get(p.keyword).position) {
    bestPosUrl.set(p.keyword, {url: p.url, position: p.position});
  }
}
for (const g of gapItems) {
  const existing = bestPosUrl.get(g.keyword);
  if (existing) {
    g.existing_url = existing.url;
    g.existing_pos = existing.position;
    g.action = 'Optimiser';
  } else {
    g.existing_url = '';
    g.existing_pos = null;
    g.action = 'Creer';
  }
}

// === 2-LEVEL CLUSTERING VIA EMBEDDINGS ===

// Get OpenAI API key from config or env
let openaiKey;
try { openaiKey = $env.OPENAI_API_KEY; } catch(e) { openaiKey = null; }
if (!openaiKey || openaiKey === "REPLACE_WITH_YOUR_API_KEY") throw new Error("Clé API OpenAI manquante. Configurez la variable d'environnement OPENAI_API_KEY dans Settings > Environment Variables de n8n. Le workflow utilise text-embedding-3-small pour le clustering.");

const allKws = gapItems.map(g => g.keyword);
const allScores = gapItems.map(g => g.score);

// --- EMBEDDING API ---
async function getEmbeddings(keywords, apiKey) {
  const BATCH = 2000;
  const allEmbed = [];
  for (let i = 0; i < keywords.length; i += BATCH) {
    const batch = keywords.slice(i, i + BATCH);
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/embeddings',
      headers: {'Authorization': 'Bearer ' + apiKey, 'Content-Type': 'application/json'},
      body: {input: batch, model: 'text-embedding-3-small'},
      json: true
    });
    if (r.error) throw new Error('OpenAI: ' + r.error.message);
    const sorted = r.data.sort((a, b) => a.index - b.index);
    allEmbed.push(...sorted.map(d => d.embedding));
  }
  return allEmbed;
}

// --- COSINE SIMILARITY ---
function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return (Math.sqrt(na) && Math.sqrt(nb)) ? dot / (Math.sqrt(na) * Math.sqrt(nb)) : 0;
}

// --- AGGLOMERATIVE CLUSTERING (Union-Find) ---
function agglomerativeCluster(embeddings, threshold) {
  const n = embeddings.length;
  const parent = Array.from({length: n}, (_, i) => i);
  function find(x) { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
  function union(x, y) { parent[find(y)] = find(x); }

  const merges = [];
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const sim = cosine(embeddings[i], embeddings[j]);
      if (sim >= threshold) merges.push({i, j, sim});
    }
  }
  merges.sort((a, b) => b.sim - a.sim);
  for (const {i, j} of merges) union(i, j);

  const groups = new Map();
  for (let i = 0; i < n; i++) {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(i);
  }
  return groups;
}

// --- LABEL FROM KEYWORDS ---
function makeLabel(indices, keywords, scores) {
  const sorted = [...indices].sort((a, b) => (scores[b] || 0) - (scores[a] || 0));
  const topKw = keywords[sorted[0]];
  const STOPS = new Set(['de','d','des','du','le','la','les','l','un','une','et','en','a','au','aux','pour','sur','par','avec','dans','que','qui','est','ce','comment','combien','quel','quelle']);
  const words = topKw.replace(/[?!,.:;]/g, '').split(/[\s'']+/).filter(w => w.length > 2 && !STOPS.has(w.toLowerCase()));
  return words.slice(0, 4).map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ') || topKw;
}

// --- RUN CLUSTERING ---
let embeddings;
try {
  embeddings = await getEmbeddings.call(this, allKws, openaiKey);
} catch(e) {
  console.log('Embedding error: ' + e.message + ' - falling back to no clustering');
  embeddings = null;
}

const kwPage = new Map();
const kwTopic = new Map();

if (embeddings && embeddings.length === allKws.length) {
  // === HYBRID CLUSTERING: Embeddings (pages) + Keywords (topics) ===

  // Step 1: Compute adaptive page threshold from similarity distribution
  const sampleSims = [];
  const step = Math.max(1, Math.floor(allKws.length / 60));
  for (let i = 0; i < allKws.length; i += step) {
    for (let j = i + step; j < allKws.length; j += step) {
      sampleSims.push(cosine(embeddings[i], embeddings[j]));
    }
  }
  sampleSims.sort((a, b) => a - b);
  const p85 = sampleSims[Math.floor(sampleSims.length * 0.85)] || 0.82;
  const PAGE_THRESHOLD = Math.min(0.88, Math.max(0.78, p85));
  console.log('Page threshold: ' + PAGE_THRESHOLD.toFixed(3) + ' (p85=' + p85.toFixed(3) + ', n=' + allKws.length + ')');

  // Step 2: Cluster keywords into pages using embeddings
  const pageGroups = agglomerativeCluster(embeddings, PAGE_THRESHOLD);

  // Step 3: Split oversized pages (>12 KW) with tighter threshold
  const MAX_PAGE = 20;
  const pages = [];
  for (const [root, indices] of pageGroups) {
    if (indices.length <= MAX_PAGE) {
      pages.push(indices);
    } else {
      const subEmbed = indices.map(i => embeddings[i]);
      const tighter = Math.min(0.95, PAGE_THRESHOLD + 0.08);
      const subGroups = agglomerativeCluster(subEmbed, tighter);
      for (const [sr, subIdx] of subGroups) {
        pages.push(subIdx.map(si => indices[si]));
      }
    }
  }

  // Step 4: Label each page (top keyword by score, cleaned)
  const STOPS = new Set(['de','d','des','du','le','la','les','l','un','une','et','en','a','au','aux','pour','sur','par','avec','dans','que','qui','est','ce','comment','combien','quel','quelle','quoi','quand','tout','faire','son','sa','ses','mon','ma','mes','ne','pas','plus','ou','se','si']);

  function cleanLabel(kw) {
    // Preserve accents, clean punctuation, handle apostrophes properly
    const cleaned = kw
      .replace(/[?!,.:;"]/g, '')
      .replace(/['']/g, "'");
    const words = cleaned.split(/[\s]+/)
      .filter(w => {
        const lower = w.toLowerCase().replace(/'/g, '');
        return lower.length > 2 && !STOPS.has(lower) && !/^\d+$/.test(lower) 
          && !['j\'ai', 'l\'on', 'c\'est', 'n\'est', 'qu\'un', 'qu\'une', 'd\'un', 'd\'une'].includes(lower);
      });
    // Capitalize first letter, preserve rest (including accents)
    return words.slice(0, 4).map(w => {
      // Don't capitalize after apostrophe
      if (w.includes("'")) {
        const parts = w.split("'");
        return parts.map(p => p.charAt(0).toUpperCase() + p.slice(1)).join("'");
      }
      return w.charAt(0).toUpperCase() + w.slice(1);
    }).join(' ') || kw;
  }

  function pageLabel(indices) {
    const sorted = [...indices].sort((a, b) => (allScores[b] || 0) - (allScores[a] || 0));
    return cleanLabel(allKws[sorted[0]]);
  }

  // Step 5: TOPIC CLUSTERING via shared significant words (not embeddings)
  // Extract 2 most significant words per page (from the top keyword)
  function topicWords(indices) {
    const sorted = [...indices].sort((a, b) => (allScores[b] || 0) - (allScores[a] || 0));
    // Pool words from top 3 keywords of the page
    const wordFreq = new Map();
    for (const idx of sorted.slice(0, Math.min(3, sorted.length))) {
      const words = allKws[idx].toLowerCase().replace(/[?!,.:;'"]/g, '').split(/[\s'']+/)
        .filter(w => w.length > 2 && !STOPS.has(w) && !/^\d+$/.test(w));
      for (const w of words) wordFreq.set(w, (wordFreq.get(w) || 0) + 1);
    }
    // Return the 2 most frequent words (= shared theme)
    return [...wordFreq.entries()].sort((a, b) => b[1] - a[1]).slice(0, 2).map(e => e[0]);
  }

  // Assign topic to each page based on its top 2 words
  const pageTopicWords = pages.map(indices => topicWords(indices));

  // Group pages that share at least 1 significant word into the same topic
  const pageTopicId = new Array(pages.length).fill(-1);
  let nextTopic = 0;
  const topicWordMap = new Map(); // "word" -> topicId

  for (let i = 0; i < pages.length; i++) {
    const tw = pageTopicWords[i];
    let assignedTopic = -1;

    // Check if any of this page's words already belong to a topic
    for (const w of tw) {
      if (topicWordMap.has(w)) {
        assignedTopic = topicWordMap.get(w);
        break;
      }
    }

    if (assignedTopic === -1) {
      // New topic
      assignedTopic = nextTopic++;
    }

    pageTopicId[i] = assignedTopic;
    // Register all words of this page under this topic
    for (const w of tw) {
      if (!topicWordMap.has(w)) topicWordMap.set(w, assignedTopic);
    }
  }

  // Build topic labels from the highest-scoring page in each topic
  const topicPages = new Map(); // topicId -> [pageIndex]
  for (let i = 0; i < pages.length; i++) {
    const tid = pageTopicId[i];
    if (!topicPages.has(tid)) topicPages.set(tid, []);
    topicPages.get(tid).push(i);
  }

  const topicLabelMap = new Map(); // topicId -> label
  for (const [tid, pidxs] of topicPages) {
    let bestScore = -1, bestLabel = '';
    for (const pi of pidxs) {
      const maxS = Math.max(...pages[pi].map(i => allScores[i] || 0));
      if (maxS > bestScore) { bestScore = maxS; bestLabel = pageLabel(pages[pi]); }
    }
    topicLabelMap.set(tid, bestLabel);
  }

  // Step 6: Assign topic and page to each keyword
  for (let pi = 0; pi < pages.length; pi++) {
    const tid = pageTopicId[pi];
    const tLabel = topicLabelMap.get(tid);
    const pLabel = pageLabel(pages[pi]);
    const pagesInTopic = topicPages.get(tid).length;

    for (const kwIdx of pages[pi]) {
      kwTopic.set(allKws[kwIdx], tLabel);
      if (pagesInTopic === 1) {
        // Single page topic: don't duplicate label
        kwPage.set(allKws[kwIdx], tLabel);
      } else {
        kwPage.set(allKws[kwIdx], tLabel + ' > ' + pLabel);
      }
    }
  }

  console.log('Clustering: ' + pages.length + ' pages, ' + topicPages.size + ' topics (threshold=' + PAGE_THRESHOLD.toFixed(3) + ')');

  // Step 7: Post-merge isolated keywords (pages with <=2 KW) into nearest page
  // Only merge within the same topic
  const MIN_PAGE_SIZE = 3;
  const pageEmbeddings = pages.map(indices => {
    const dim = embeddings[0].length;
    const c = new Array(dim).fill(0);
    for (const idx of indices) for (let d = 0; d < dim; d++) c[d] += embeddings[idx][d];
    for (let d = 0; d < dim; d++) c[d] /= indices.length;
    return c;
  });

  // Track which pages to merge into which
  const mergeInto = new Array(pages.length).fill(-1); // -1 = keep as-is

  for (let pi = 0; pi < pages.length; pi++) {
    if (pages[pi].length > MIN_PAGE_SIZE) continue; // skip pages that are big enough

    // Find nearest page ACROSS ALL TOPICS (cross-topic merge)
    let bestSim = -1, bestTarget = -1;
    for (let spi = 0; spi < pages.length; spi++) {
      if (spi === pi) continue;
      if (mergeInto[spi] !== -1) continue;
      if (pages[spi].length <= MIN_PAGE_SIZE) continue; // merge into bigger pages only
      const sim = cosine(pageEmbeddings[pi], pageEmbeddings[spi]);
      if (sim > bestSim) { bestSim = sim; bestTarget = spi; }
    }

    // Merge if similarity is high enough (>0.72 cross-topic)
    if (bestTarget !== -1 && bestSim > 0.68) {
      mergeInto[pi] = bestTarget;
    }
  }

  // Apply merges
  for (let pi = 0; pi < pages.length; pi++) {
    if (mergeInto[pi] !== -1) {
      pages[mergeInto[pi]].push(...pages[pi]);
      pages[pi] = []; // empty it
    }
  }

  // Remove empty pages and rebuild assignments
  const finalPages = pages.filter(p => p.length > 0);
  kwTopic.clear();
  kwPage.clear();

  // Rebuild topic assignments (topic structure hasn't changed, just page contents)
  const finalPageTopicId = [];
  for (let pi = 0; pi < pages.length; pi++) {
    if (pages[pi].length > 0) {
      finalPageTopicId.push(pageTopicId[pi]);
    }
  }

  // Rebuild topicPages
  const finalTopicPages = new Map();
  for (let i = 0; i < finalPages.length; i++) {
    const tid = finalPageTopicId[i];
    if (!finalTopicPages.has(tid)) finalTopicPages.set(tid, []);
    finalTopicPages.get(tid).push(i);
  }

  // Rebuild topic labels
  const finalTopicLabels = new Map();
  for (const [tid, pidxs] of finalTopicPages) {
    let bestScore = -1, bestLabel = '';
    for (const pi of pidxs) {
      const maxS = Math.max(...finalPages[pi].map(i => allScores[i] || 0));
      if (maxS > bestScore) { bestScore = maxS; bestLabel = pageLabel(finalPages[pi]); }
    }
    finalTopicLabels.set(tid, bestLabel);
  }

  // Final assignment
  for (let pi = 0; pi < finalPages.length; pi++) {
    const tid = finalPageTopicId[pi];
    const tLabel = finalTopicLabels.get(tid);
    const pLabel = pageLabel(finalPages[pi]);
    const pagesInTopic = finalTopicPages.get(tid).length;

    for (const kwIdx of finalPages[pi]) {
      kwTopic.set(allKws[kwIdx], tLabel);
      if (pagesInTopic === 1) {
        kwPage.set(allKws[kwIdx], tLabel);
      } else {
        kwPage.set(allKws[kwIdx], tLabel + ' > ' + pLabel);
      }
    }
  }

  const mergedCount = mergeInto.filter(m => m !== -1).length;
  console.log('Post-merge: ' + mergedCount + ' small pages absorbed. Final: ' + finalPages.length + ' pages, ' + finalTopicPages.size + ' topics');


} else {
  // Fallback: no clustering
  for (const kw of allKws) {
    kwTopic.set(kw, 'Non classe');
    kwPage.set(kw, 'Non classe');
  }
}

